using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Threading;
using System.Threading.Tasks;
namespace Monja {
 public sealed class ScanResult {public List<Edge> Edges=new List<Edge>();public List<string> Diagnostics=new List<string>();public int WorkbooksScanned,WorksheetsScanned,FormulaCellsScanned;}
 public sealed class ExcelScanner {
  readonly dynamic app;public ExcelScanner(object application){app=application;}
  public static void Release(object o){if(o==null)return;try{if(Marshal.IsComObject(o))Marshal.ReleaseComObject(o);}catch(InvalidComObjectException){}catch(COMException ex){if(ex.ErrorCode!=unchecked((int)0x80010114)&&ex.ErrorCode!=unchecked((int)0x80010108))throw;}}
  public async Task<ScanResult> Scan(HashSet<string> targets,bool extendedVba,CancellationToken cancel,IProgress<string> progress,bool includeVba=true){
   if(Thread.CurrentThread.GetApartmentState()!=ApartmentState.STA)throw new InvalidOperationException("Excel COM requires the Excel STA thread");
   var output=new ScanResult();dynamic books=null;
   try{books=app.Workbooks;int count=books.Count;for(int bi=1;bi<=count;bi++){
    cancel.ThrowIfCancellationRequested();dynamic book=null,sheets=null;try{book=books.Item[bi];string id=Identity(book);if(!targets.Contains(id))continue;output.WorkbooksScanned++;sheets=book.Worksheets;var ctx=new Context{Book=id};var inputs=new List<FormulaInput>();var moduleSheets=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
     for(int si=1;si<=sheets.Count;si++){dynamic s=null;try{s=sheets.Item[si];ctx.Sheets.Add((string)s.Name);try{moduleSheets[(string)s.CodeName]=(string)s.Name;}catch(Exception ex)when(IsOfficeFailure(ex)){output.Diagnostics.Add("Worksheet.CodeName: "+Failure(ex));}}finally{Release((object)s);}}
     dynamic names=null;try{names=book.Names;for(int ni=1;ni<=names.Count;ni++){dynamic n=null;try{n=names.Item(ni);ctx.Names[(string)n.Name]=(string)n.RefersTo;}finally{Release((object)n);}}}catch(Exception ex)when(IsOfficeFailure(ex)){output.Diagnostics.Add("Workbook.Names: "+Failure(ex));}finally{Release((object)names);}
     // Tables are collected before formulas so references to later sheets resolve.
     for(int si=1;si<=sheets.Count;si++){dynamic s=null,tables=null;try{s=sheets.Item[si];tables=s.ListObjects;for(int ti=1;ti<=tables.Count;ti++){dynamic table=null,range=null,columns=null;try{table=tables.Item(ti);range=table.Range;columns=table.ListColumns;var cols=new string[columns.Count];for(int ci=1;ci<=columns.Count;ci++){dynamic col=null;try{col=columns.Item(ci);cols[ci-1]=col.Name;}finally{Release((object)col);}}ctx.Tables[(string)table.Name]=new TableInfo{Sheet=s.Name,Address=range.Address[false,false,1],Columns=cols};}finally{Release((object)columns);Release((object)range);Release((object)table);}}}catch(Exception ex)when(IsOfficeFailure(ex)){output.Diagnostics.Add("Worksheet.ListObjects: "+Failure(ex));}finally{Release((object)tables);Release((object)s);}await Task.Delay(1);cancel.ThrowIfCancellationRequested();}
     for(int si=1;si<=sheets.Count;si++){
      cancel.ThrowIfCancellationRequested();dynamic sheet=null,used=null,formulas=null,areas=null;
      try{sheet=sheets.Item[si];string sheetName=sheet.Name;output.WorksheetsScanned++;ctx.Sheet=sheetName;progress.Report(id+" / "+sheetName);used=sheet.UsedRange;
       bool fallback=false;try{formulas=used.SpecialCells(-4123,Type.Missing);}catch(Exception ex)when(IsOfficeFailure(ex)){object hasFormula=null;try{hasFormula=used.HasFormula;}catch(Exception metadata)when(IsOfficeFailure(metadata)){}if(!(hasFormula is bool)|| (bool)hasFormula){fallback=true;output.Diagnostics.Add("Range.SpecialCells: "+Failure(ex)+" / bounded formula-read fallback");}}
       if(formulas!=null){areas=formulas.Areas;for(int ai=1;ai<=areas.Count;ai++){dynamic area=null;try{area=areas.Item[ai];await ReadFormulaRange((object)sheet,(object)area,id,sheetName,inputs,cancel,progress);
       }finally{Release((object)area);}}}
       if(fallback)await ReadFormulaRange((object)sheet,(object)used,id,sheetName,inputs,cancel,progress,2000000);
       try{await CollectCharts(sheet,id,sheetName,inputs,output,cancel);}catch(Exception ex)when(IsOfficeFailure(ex)){output.Diagnostics.Add("Worksheet.ChartObjects: "+Failure(ex));}
       try{await CollectPivots(sheet,id,sheetName,inputs,output,cancel);}catch(Exception ex)when(IsOfficeFailure(ex)){output.Diagnostics.Add("Worksheet.PivotTables: "+Failure(ex));}
      }catch(Exception ex)when(IsOfficeFailure(ex)){output.Diagnostics.Add("Worksheet formula read: "+Failure(ex));}finally{Release((object)areas);Release((object)formulas);Release((object)used);Release((object)sheet);}
      var batch=inputs.ToArray();output.FormulaCellsScanned+=inputs.FindAll(x=>x.Kind=="formula").Count;inputs.Clear();var localCtx=new Context{Book=id,Sheet=ctx.Sheet,Sheets=ctx.Sheets,Names=ctx.Names,Tables=ctx.Tables};
      var parsed=await Task.Run(()=>{var edges=new List<Edge>();foreach(var input in batch){cancel.ThrowIfCancellationRequested();edges.AddRange(FormulaParser.Parse(input,localCtx));if(edges.Count>500000)throw new InvalidOperationException("Reference limit reached");}return edges;},cancel);output.Edges.AddRange(parsed);if(output.Edges.Count>500000)throw new InvalidOperationException("Reference limit reached (500000)");
     }
     dynamic charts=null;try{charts=book.Charts;for(int ci=1;ci<=charts.Count;ci++){dynamic chart=null;try{chart=charts.Item[ci];var chartInputs=new List<FormulaInput>();cancel.ThrowIfCancellationRequested();ReadSeries(chart,id,(string)chart.Name,(string)chart.Name,null,chartInputs,cancel);ctx.Sheet=chart.Name;foreach(var input in chartInputs)output.Edges.AddRange(FormulaParser.Parse(input,ctx));}finally{Release((object)chart);}}}catch(Exception ex)when(IsOfficeFailure(ex)){output.Diagnostics.Add("Workbook.Charts: "+Failure(ex));}finally{Release((object)charts);}
     try{if(includeVba){if(extendedVba)await ReadVba(book,id,output,moduleSheets,cancel);else{string filename=book.FullName;string extension=System.IO.Path.GetExtension(filename).ToLowerInvariant();if(extension==".xlsm"||extension==".xlam"||extension==".xlsb"){bool saved=book.Saved;if(!System.IO.File.Exists(filename))output.Diagnostics.Add(id+": VBA standard mode requires a saved file. Save explicitly or choose extended mode.");else{if(!saved)output.Diagnostics.Add(id+": saved-file VBA excludes unsaved code changes.");try{var savedEdges=await Task.Run(()=>{var found=new List<Edge>();foreach(var module in SavedVbaReader.Read(filename,cancel)){cancel.ThrowIfCancellationRequested();string sheetContext;moduleSheets.TryGetValue(module.Name,out sheetContext);var parsed=VbaParser.Parse(module.Code,id,module.Name,sheetContext,cancel);foreach(var edge in parsed)edge.Method="vba-saved-file";found.AddRange(parsed);if(found.Count>500000)throw new InvalidOperationException("VBA reference limit reached");}return found;},cancel);output.Edges.AddRange(savedEdges);}catch(OperationCanceledException){throw;}catch(Exception ex){output.Diagnostics.Add(id+": saved VBA: "+ex.Message);}}}}}}catch(Exception ex)when(IsOfficeFailure(ex)){output.Diagnostics.Add("Workbook VBA metadata: "+Failure(ex));}
    }catch(Exception ex)when(IsOfficeFailure(ex)){output.Diagnostics.Add("Workbook metadata: "+Failure(ex));}finally{Release((object)sheets);Release((object)book);}await Task.Delay(1);
   }}finally{Release((object)books);}
   if(output.Edges.Count>500000)throw new InvalidOperationException("Reference limit reached (500000)");
   foreach(var edge in output.Edges){if(targets.Contains(edge.Source.Book))continue;var matches=new List<string>();foreach(string id in targets)if(String.Equals(System.IO.Path.GetFileName(id),edge.Source.Book,StringComparison.OrdinalIgnoreCase))matches.Add(id);if(matches.Count==1)edge.Source.Book=matches[0];else if(matches.Count>1){edge.Certainty="unknown";edge.Method="ambiguous-workbook/"+edge.Method;}}
   return output;
  }
  public static bool IsOfficeFailure(Exception ex){return ex is COMException||ex is NotImplementedException||ex is UnauthorizedAccessException;}
  static string Failure(Exception ex){return ex.GetType().Name+" (0x"+ex.HResult.ToString("X8")+"): "+ex.Message;}
  static async Task ReadFormulaRange(dynamic sheet,dynamic area,string id,string sheetName,List<FormulaInput> inputs,CancellationToken cancel,IProgress<string> progress,long maximumCells=Int64.MaxValue){dynamic areaRows=null,areaColumns=null;try{areaRows=area.Rows;areaColumns=area.Columns;int rows=areaRows.Count,cols=areaColumns.Count,startRow=area.Row,startCol=area.Column;if((long)rows*cols>maximumCells)throw new COMException("Formula fallback exceeds 2,000,000 cells; this sheet was not fully read.");int chunk=Math.Max(1,20000/cols);for(int r=0;r<rows;r+=chunk){cancel.ThrowIfCancellationRequested();dynamic range=null;try{string address=Graph.Letters(startCol)+(startRow+r)+":"+Graph.Letters(startCol+cols-1)+(startRow+Math.Min(rows,r+chunk)-1);range=sheet.Range[address];object values=range.Formula;Array array=values as Array;int height=Math.Min(chunk,rows-r);for(int y=0;y<height;y++)for(int x=0;x<cols;x++){string formula=Convert.ToString(array==null?values:array.GetValue(y+array.GetLowerBound(0),x+array.GetLowerBound(1)));if(formula.StartsWith("="))inputs.Add(new FormulaInput{Text=formula,Target=new Location{Book=id,Sheet=sheetName,Address=Graph.Letters(startCol+x)+(startRow+r+y),Kind="cell"}});}if(inputs.Count>500000)throw new InvalidOperationException("Formula limit reached (500000)");}finally{Release((object)range);}progress.Report(sheetName+" / "+inputs.Count);await Task.Delay(1);}}finally{Release((object)areaColumns);Release((object)areaRows);}}
  public static string Identity(dynamic book){try{return (string)book.FullName;}catch{return (string)book.Name;}}
  static async Task CollectCharts(dynamic sheet,string book,string name,List<FormulaInput> inputs,ScanResult result,CancellationToken cancel){dynamic charts=null;try{charts=sheet.ChartObjects();for(int i=1;i<=charts.Count;i++){dynamic obj=null,chart=null,anchor=null;try{obj=charts.Item(i);chart=obj.Chart;string address=null;try{anchor=obj.TopLeftCell;address=anchor.Address[false,false,1];}catch(COMException){}cancel.ThrowIfCancellationRequested();ReadSeries(chart,book,name,(string)obj.Name,address,inputs,cancel);}catch(Exception ex)when(IsOfficeFailure(ex)){result.Diagnostics.Add("Chart.SeriesCollection: "+Failure(ex));}finally{Release((object)anchor);Release((object)chart);Release((object)obj);}await Task.Delay(1);}}finally{Release((object)charts);}}
  static void ReadSeries(dynamic chart,string book,string sheet,string name,string address,List<FormulaInput> inputs,CancellationToken cancel){dynamic series=null;try{series=chart.SeriesCollection();for(int i=1;i<=series.Count;i++){dynamic s=null;try{cancel.ThrowIfCancellationRequested();s=series.Item(i);inputs.Add(new FormulaInput{Text=s.Formula,Kind="chart",Target=new Location{Book=book,Sheet=sheet,Name=name,Address=address,Kind="chart"}});}finally{Release((object)s);}}}finally{Release((object)series);}}
  static async Task CollectPivots(dynamic sheet,string book,string name,List<FormulaInput> inputs,ScanResult result,CancellationToken cancel){dynamic pivots=null;try{pivots=sheet.PivotTables();for(int i=1;i<=pivots.Count;i++){dynamic pt=null,range=null,cache=null;try{cancel.ThrowIfCancellationRequested();pt=pivots.Item(i);range=pt.TableRange2;cache=pt.PivotCache();string addr=Graph.Letters((int)range.Column)+range.Row;
    if((int)cache.SourceType!=1){string connection="External / model / OLAP";dynamic wbConnection=null;try{wbConnection=cache.WorkbookConnection;connection=wbConnection.Name;}catch(COMException){}finally{Release((object)wbConnection);}result.Edges.Add(new Edge{Id=Guid.NewGuid().ToString("N"),Kind="pivot",Source=new Location{Book=book,Kind="external",Name=connection},Target=new Location{Book=book,Sheet=name,Address=addr,Kind="pivot",Name=pt.Name},Certainty="unknown",Method="pivot-external-connection",Content=connection});result.Diagnostics.Add(book+" / "+name+" / "+pt.Name+": external/model pivot source unavailable / "+connection);continue;}
    string source=Convert.ToString(cache.SourceData);source=RegexR1C1(source);inputs.Add(new FormulaInput{Text=source,Kind="pivot",Target=new Location{Book=book,Sheet=name,Address=addr,Kind="pivot",Name=pt.Name}});
   }catch(Exception ex)when(IsOfficeFailure(ex)){result.Diagnostics.Add("PivotTable.SourceData: "+Failure(ex));}finally{Release((object)cache);Release((object)range);Release((object)pt);}await Task.Delay(1);}}finally{Release((object)pivots);}}
  static string RegexR1C1(string value){return System.Text.RegularExpressions.Regex.Replace(value,@"R([1-9]\d*)C([1-9]\d*)",m=>Graph.Letters(Int32.Parse(m.Groups[2].Value))+m.Groups[1].Value);}
  static async Task ReadVba(dynamic book,string id,ScanResult result,Dictionary<string,string> moduleSheets,CancellationToken cancel){dynamic project=null,components=null;try{project=book.VBProject;if((int)project.Protection!=0){result.Diagnostics.Add(id+": VBA project is protected; code was not read");return;}components=project.VBComponents;for(int i=1;i<=components.Count;i++){dynamic component=null,code=null;try{cancel.ThrowIfCancellationRequested();component=components.Item(i);code=component.CodeModule;int count=code.CountOfLines;if(count==0)continue;string sheet;moduleSheets.TryGetValue((string)component.Name,out sheet);if(count>500000)throw new InvalidOperationException("VBA module line limit reached");string text=code.Lines[1,count],moduleName=component.Name;result.Edges.AddRange(await Task.Run(()=>VbaParser.Parse(text,id,moduleName,sheet,cancel),cancel));if(result.Edges.Count>500000)throw new InvalidOperationException("Reference limit reached");}finally{Release((object)code);Release((object)component);}}}catch(Exception ex)when(IsOfficeFailure(ex)){result.Diagnostics.Add(id+": VBA access denied. Enable Trust access to the VBA project object model only if permitted by your organization, then restart Excel. No setting was changed.");}finally{Release((object)components);Release((object)project);}}
 }
}

